use vstd::prelude::*;

verus! {

/// A simple row-major matrix type.
pub type Matrix<T> = Vec<Vec<T>>;

/// Spec-level description of broadcasting:
/// If `a.len() == r`, then ret[i][j] = a[i] (column-vector semantics).
/// If `a.len() == c`, then ret[i][j] = a[j] (row-vector semantics).
spec fn broadcast_spec(a: Seq<i8>, r: nat, c: nat) -> Seq<Seq<i8>> {
    Seq::new(r, |i: nat|
        Seq::new(c, |j: nat|
            if a.len() == r { a[i] } else { a[j] }
        )
    )
}

/// Useful helper: every row has length `c`.
spec fn rows_have_len(m: Seq<Seq<i8>>, c: nat) -> bool {
    forall|i: nat| i < m.len() ==> m[i].len() == c
}

pub fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> (ret: Matrix<i8>)
    requires
        a.len() > 0,
        shape.len() == 2,
        (shape[0] as nat) > 0,
        (shape[1] as nat) > 0,
        a.len() == shape[0] as nat || a.len() == shape[1] as nat,
    ensures
        ret@.len() == shape[0] as nat,
        rows_have_len(ret@, shape[1] as nat),
        ret@ == broadcast_spec(a@, shape[0] as nat, shape[1] as nat),
{
    assert!(!a.is_empty(), "input array must have positive length");
    assert!(shape.len() == 2, "shape must have length 2");
    let r = shape[0] as usize;
    let c = shape[1] as usize;
    assert!(r > 0 && c > 0, "shape entries must be positive");

    let n = a.len();
    assert!(
        n == r || n == c,
        "array length must match either R or C for broadcasting"
    );

    let mut ret: Matrix<i8> = Vec::with_capacity(r);

    if n == r {
        // Column-vector semantics: ret[i][j] = a[i]
        for i in 0..r
            invariant
                r > 0,
                c > 0,
                n == r,
                n == a.len(),
                ret@.len() == i as nat,
                rows_have_len(ret@, c as nat),
                ret@ == broadcast_spec(a@, r as nat, c as nat).subrange(0, i as int),
            decreases r - i
        {
            let val = a[i];
            let mut row = Vec::with_capacity(c);
            row.resize(c, val);

            // Show this row matches the spec: all entries are `a[i]`.
            proof {
                assert(row@.len() == c as nat);
                assert(forall|j: nat| j < c as nat ==> row@[j] == a@[i as nat]);
            }

            ret.push(row);

            proof {
                // After push, ret matches the spec prefix one longer.
                assert(ret@.len() == (i + 1) as nat);
                assert(ret@ == broadcast_spec(a@, r as nat, c as nat).subrange(0, (i + 1) as int));
            }
        }
    } else {
        // Row-vector semantics: ret[i][j] = a[j]
        for k in 0..r
            invariant
                r > 0,
                c > 0,
                n == c,
                n == a.len(),
                ret@.len() == k as nat,
                rows_have_len(ret@, c as nat),
                ret@ == broadcast_spec(a@, r as nat, c as nat).subrange(0, k as int),
            decreases r - k
        {
            ret.push(a.clone());

            proof {
                // The pushed row is exactly `a@`, hence matches the spec row.
                assert(ret@[k as nat] == a@);
                assert(ret@[k as nat].len() == c as nat);
                assert(ret@ == broadcast_spec(a@, r as nat, c as nat).subrange(0, (k + 1) as int));
            }
        }
    }

    ret
}

} // verus!

